
const http=require('node:http');const {pathToFileURL}=require('node:url');
function getJson(url){return new Promise((res,rej)=>http.get(url,r=>{let d='';r.on('data',c=>d+=c);r.on('end',()=>res(JSON.parse(d)))}).on('error',rej));}
(async()=>{const list=await getJson('http://127.0.0.1:9223/json/list');const page=list.find(x=>x.type==='page');const ws=new WebSocket(page.webSocketDebuggerUrl);await new Promise((r,j)=>{ws.addEventListener('open',r,{once:true});ws.addEventListener('error',j,{once:true})});let n=0;const pend=new Map();const exceptions=[];ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.method==='Runtime.exceptionThrown')exceptions.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text);if(m.id&&pend.has(m.id)){const p=pend.get(m.id);pend.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result)}});const call=(method,params={})=>new Promise((res,rej)=>{const id=++n;pend.set(id,{resolve:res,reject:rej});ws.send(JSON.stringify({id,method,params}))});const ev=async expression=>(await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result.value;const sleep=ms=>new Promise(r=>setTimeout(r,ms));await call('Runtime.enable');await call('Page.enable');await call('Page.navigate',{url:pathToFileURL('D:/aiapp竞品调研/prototypes/entry_changes/main_top_navigation.html').href});await sleep(1400);await ev("document.querySelector('.phone-a [data-screen=\"watchlist\"]').click()");await ev("document.querySelectorAll('.phone-a .sort-head')[0].click();document.querySelectorAll('.phone-a .sort-head')[0].click();");await sleep(100);const sort=await ev("JSON.stringify({first:document.querySelector('.phone-a .stock-table tbody tr .stock-name').textContent,cls:document.querySelector('.phone-a .sort-head').className})");await ev("const i=document.querySelector('.phone-a .ai-input');i.value='测试问题';i.dispatchEvent(new Event('input',{bubbles:true}));document.querySelector('.phone-a .composer').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));");await sleep(100);const chat=await ev("JSON.stringify({chatActive:document.querySelector('.phone-a [data-view=\"chat\"]').classList.contains('active'),question:document.querySelector('.phone-a .latest-question').textContent,bScreens:document.querySelectorAll('.phone-b .screen').length,bHome:document.querySelector('.phone-b [data-view=\"home\"]')!==null})");console.log(JSON.stringify({sort:JSON.parse(sort),chat:JSON.parse(chat),exceptions}));ws.close();})().catch(e=>{console.error(e);process.exit(1)});
